-- Check if enforcementactions.invdetref matches investigationdetails.invdetreg
SELECT COUNT(*) FROM enforcementactions ea
JOIN investigationdetails id ON ea.invdetref = id.invdetreg;

-- Check investigationdetails.sentref and sentimentandfundamentals.sentreg
SELECT COUNT(*) FROM investigationdetails id
JOIN sentimentandfundamentals sf ON id.sentref = sf.sentreg;

-- Check sentimentandfundamentals.trdref2 and trader.tradereg
SELECT COUNT(*) FROM sentimentandfundamentals sf
JOIN trader t ON sf.trdref2 = t.tradereg;
